182: fn confirmation_prompt_from_data(data: &serde_json::Value) -> Option<ConfirmationPrompt> {
183:     if data
184:         .get("confirmation_required")
185:         .and_then(|v| v.as_bool())
186:         .unwrap_or(false)
187:     {
188:         let action = data
189:             .get("action")
190:             .and_then(|v| v.as_str())
191:             .unwrap_or("")
192:             .to_string();
193:         return Some(ConfirmationPrompt {
194:             action: action.clone(),
195:             category: data
196:                 .get("category")
197:                 .and_then(|v| v.as_str())
198:                 .unwrap_or("")
199:                 .to_string(),
200:             description: data
201:                 .get("description")
202:                 .and_then(|v| v.as_str())
203:                 .filter(|s| !s.is_empty())
204:                 .unwrap_or(action.as_str())
205:                 .to_string(),
206:             confirmation_id: data
207:                 .get("confirmation_id")
208:                 .and_then(|v| v.as_str())
209:                 .unwrap_or("")
210:                 .to_string(),
211:         });
212:     }
213: 
214:     data.get("result")
215:         .and_then(|v| v.get("data"))
216:         .and_then(confirmation_prompt_from_data)
217: }
