223: fn run_interactive_confirmations(
224:     mut resp: Response,
225:     flags: &Flags,
226:     output_opts: &OutputOptions,
227: ) -> Response {
228:     while let Some(prompt) = confirmation_prompt_from_response(&resp) {
229:         eprintln!("[agent-browser] Action requires confirmation:");
230:         if prompt.category.is_empty() {
231:             eprintln!("  {}", prompt.description);
232:         } else {
233:             eprintln!("  {}: {}", prompt.category, prompt.description);
234:         }
235:         eprint!("  Allow? [y/N]: ");
236: 
237:         let mut input = String::new();
238:         let approved = if std::io::IsTerminal::is_terminal(&std::io::stdin()) {
239:             std::io::stdin().read_line(&mut input).is_ok()
240:                 && matches!(input.trim().to_lowercase().as_str(), "y" | "yes")
241:         } else {
242:             false
243:         };
244: 
245:         let confirm_cmd = if approved {
246:             json!({
247:                 "id": gen_id(),
248:                 "action": "confirm",
249:                 "confirmationId": prompt.confirmation_id
250:             })
251:         } else {
252:             json!({
253:                 "id": gen_id(),
254:                 "action": "deny",
255:                 "confirmationId": prompt.confirmation_id
256:             })
257:         };
258: 
259:         match send_command(confirm_cmd, &flags.session) {
260:             Ok(next_resp) => {
261:                 if !approved {
262:                     eprintln!("{} Action denied", color::error_indicator());
263:                     exit(1);
264:                 }
265:                 resp = next_resp;
266:             }
267:             Err(e) => {
268:                 eprintln!("{} {}", color::error_indicator(), e);
269:                 exit(1);
270:             }
271:         }
272:     }
273: 
274:     print_response_with_opts(&resp, None, output_opts);
275:     resp
276: }
