284: fn parse_proxy(proxy_str: &str) -> ParsedProxy {
285:     let Some(protocol_end) = proxy_str.find("://") else {
286:         return ParsedProxy {
287:             server: proxy_str.to_string(),
288:             username: None,
289:             password: None,
290:         };
291:     };
292:     let protocol = &proxy_str[..protocol_end + 3];
293:     let rest = &proxy_str[protocol_end + 3..];
294: 
295:     let Some(at_pos) = rest.rfind('@') else {
296:         return ParsedProxy {
297:             server: proxy_str.to_string(),
298:             username: None,
299:             password: None,
300:         };
301:     };
302: 
303:     let creds = &rest[..at_pos];
304:     let server_part = &rest[at_pos + 1..];
305:     let server = format!("{}{}", protocol, server_part);
306: 
307:     let (username, password) = match creds.find(':') {
308:         Some(colon_pos) => {
309:             let u = &creds[..colon_pos];
310:             let p = &creds[colon_pos + 1..];
311:             (
312:                 if u.is_empty() {
313:                     None
314:                 } else {
315:                     Some(u.to_string())
316:                 },
317:                 if p.is_empty() {
318:                     None
319:                 } else {
320:                     Some(p.to_string())
321:                 },
322:             )
323:         }
324:         None => (
325:             if creds.is_empty() {
326:                 None
327:             } else {
328:                 Some(creds.to_string())
329:             },
330:             None,
331:         ),
332:     };
333: 
334:     ParsedProxy {
335:         server,
336:         username,
337:         password,
338:     }
339: }
