403: fn git_toplevel() -> Option<PathBuf> {
404:     let output = Command::new("git")
405:         .args(["rev-parse", "--show-toplevel"])
406:         .output()
407:         .ok()?;
408:     if !output.status.success() {
409:         return None;
410:     }
411:     let raw = String::from_utf8(output.stdout).ok()?;
412:     let path = raw.trim();
