420: fn resolve_session_id_scope(scope: &str) -> Result<(String, PathBuf), String> {
421:     match scope {
422:         "worktree" => {
423:             let path = git_toplevel().unwrap_or_else(|| {
424:                 canonical_path(env::current_dir().unwrap_or_else(|_| PathBuf::from(".")))
425:             });
426:             Ok(("worktree".to_string(), path))
427:         }
428:         "cwd" => {
429:             let path = canonical_path(env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
430:             Ok(("cwd".to_string(), path))
431:         }
432:         "git-root" => git_toplevel()
433:             .map(|path| ("git-root".to_string(), path))
434:             .ok_or_else(|| "Not inside a Git working tree".to_string()),
435:         other => Err(format!(
436:             "Unknown session id scope '{}'. Use worktree, cwd, or git-root.",
437:             other
438:         )),
439:     }
