447:     let mut i = 2;
448:     while i < args.len() {
449:         match args[i].as_str() {
450:             "--scope" => {
451:                 if let Some(value) = args.get(i + 1) {
452:                     scope = value.clone();
453:                     i += 1;
454:                 }
455:             }
456:             "--prefix" => {
457:                 if let Some(value) = args.get(i + 1) {
458:                     prefix = Some(value.clone());
459:                     i += 1;
460:                 }
461:             }
462:             "--json" => json_output = true,
463:             _ => {}
464:         }
465:         i += 1;
466:     }
467: 
468:     let (resolved_scope, path) = match resolve_session_id_scope(&scope) {
469:         Ok(result) => result,
470:         Err(e) => {
471:             if json_output {
472:                 print_json_error(e);
473:             } else {
474:                 eprintln!("{} {}", color::error_indicator(), e);
475:             }
476:             exit(1);
477:         }
478:     };
479: 
480:     let path_str = path.to_string_lossy().to_string();
481:     let mut hasher = Sha256::new();
482:     hasher.update(path_str.as_bytes());
483:     let hash = format!("{:x}", hasher.finalize());
484:     let suffix = &hash[..12];
485: 
486:     let prefix = prefix
487:         .as_deref()
488:         .map(validation::sanitize_session_component)
489:         .filter(|s| !s.is_empty());
490:     let session = match prefix {
491:         Some(prefix) => format!("{}-{}", prefix, suffix),
492:         None => suffix.to_string(),
493:     };
494: 
495:     if json_output {
496:         print_json_value(json!({
497:             "success": true,
498:             "data": {
499:                 "session": session,
500:                 "scope": resolved_scope,
501:                 "path": path_str,
502:                 "hash": suffix
503:             }
504:         }));
505:     } else {
506:         println!("{}", session);
507:     }
508: }
