633: fn run_dashboard_start(port: u16, json_mode: bool) {
634:     let pid_path = get_dashboard_pid_path();
635: 
636:     // Check if already running
637:     if let Ok(pid_str) = fs::read_to_string(&pid_path) {
638:         if let Ok(pid) = pid_str.trim().parse::<u32>() {
639:             if is_pid_alive(pid) {
640:                 if json_mode {
641:                     print_json_value(json!({
642:                         "success": true,
643:                         "data": { "port": port, "pid": pid, "already_running": true },
644:                     }));
645:                 } else {
646:                     println!("Dashboard already running at http://localhost:{}", port);
647:                 }
648:                 return;
649:             }
650:         }
651:         let _ = fs::remove_file(&pid_path);
652:     }
653: 
654:     let socket_dir = get_socket_dir();
655:     if !socket_dir.exists() {
656:         let _ = fs::create_dir_all(&socket_dir);
657:     }
658: 
659:     let exe_path = match env::current_exe() {
660:         Ok(p) => p.canonicalize().unwrap_or(p),
661:         Err(e) => {
662:             if json_mode {
663:                 print_json_error(format!("Failed to get executable path: {}", e));
664:             } else {
665:                 eprintln!(
666:                     "{} Failed to get executable path: {}",
667:                     color::error_indicator(),
668:                     e
669:                 );
670:             }
671:             exit(1);
672:         }
673:     };
674: 
675:     let mut cmd = std::process::Command::new(&exe_path);
676:     cmd.env("AGENT_BROWSER_DASHBOARD", "1")
677:         .env("AGENT_BROWSER_DASHBOARD_PORT", port.to_string());
678: 
679:     #[cfg(unix)]
680:     {
681:         use std::os::unix::process::CommandExt;
682:         unsafe {
683:             cmd.pre_exec(|| {
684:                 libc::setsid();
685:                 Ok(())
686:             });
687:         }
688:     }
689: 
690:     #[cfg(windows)]
691:     {
692:         use std::os::windows::process::CommandExt;
693:         const CREATE_NEW_PROCESS_GROUP: u32 = 0x00000200;
694:         const DETACHED_PROCESS: u32 = 0x00000008;
695:         cmd.creation_flags(CREATE_NEW_PROCESS_GROUP | DETACHED_PROCESS);
696:     }
697: 
698:     match cmd
699:         .stdin(std::process::Stdio::null())
700:         .stdout(std::process::Stdio::null())
701:         .stderr(std::process::Stdio::null())
702:         .spawn()
703:     {
704:         Ok(child) => {
705:             let pid = child.id();
706:             let _ = fs::write(&pid_path, pid.to_string());
707: 
708:             if json_mode {
709:                 print_json_value(json!({
710:                     "success": true,
711:                     "data": { "port": port, "pid": pid },
712:                 }));
713:             } else {
714:                 println!("Dashboard started at http://localhost:{}", port);
715:             }
716:         }
717:         Err(e) => {
718:             if json_mode {
719:                 print_json_error(format!("Failed to start dashboard: {}", e));
720:             } else {
721:                 eprintln!(
722:                     "{} Failed to start dashboard: {}",
723:                     color::error_indicator(),
724:                     e
725:                 );
726:             }
727:             exit(1);
728:         }
729:     }
730: }
