732: fn run_dashboard_stop(json_mode: bool) {
733:     let pid_path = get_dashboard_pid_path();
734: 
735:     let pid_str = match fs::read_to_string(&pid_path) {
736:         Ok(s) => s,
737:         Err(_) => {
738:             if json_mode {
739:                 print_json_value(
740:                     json!({ "success": true, "data": { "stopped": false, "reason": "not running" } }),
741:                 );
742:             } else {
743:                 println!("Dashboard is not running");
744:             }
745:             return;
746:         }
747:     };
748: 
749:     let pid: u32 = match pid_str.trim().parse() {
750:         Ok(p) => p,
751:         Err(_) => {
752:             let _ = fs::remove_file(&pid_path);
753:             if json_mode {
754:                 print_json_value(
755:                     json!({ "success": true, "data": { "stopped": false, "reason": "invalid pid" } }),
756:                 );
757:             } else {
758:                 println!("Dashboard is not running");
759:             }
760:             return;
761:         }
762:     };
763: 
764:     #[cfg(unix)]
765:     {
766:         unsafe {
767:             libc::kill(pid as i32, libc::SIGTERM);
768:         }
769:     }
770:     #[cfg(windows)]
771:     {
772:         unsafe {
773:             let handle = OpenProcess(1, 0, pid); // PROCESS_TERMINATE = 1
774:             if handle != 0 {
775:                 windows_sys::Win32::System::Threading::TerminateProcess(handle, 0);
776:                 CloseHandle(handle);
777:             }
778:         }
779:     }
780: 
781:     let _ = fs::remove_file(&pid_path);
782: 
783:     if json_mode {
784:         print_json_value(json!({ "success": true, "data": { "stopped": true } }));
785:     } else {
786:         println!("{} Dashboard stopped", color::green("✓"));
787:     }
788: }
