790: fn run_close_all(flags: &Flags) {
791:     // walk_daemons auto-cleans stale .pid / .sock / .stream sidecar files and
792:     // separates out the standalone dashboard. We only want to send `close` to
793:     // real session daemons; the dashboard has its own `dashboard stop`.
794:     let inventory = walk_daemons();
795:     let sessions: Vec<(String, u32)> = inventory
796:         .sessions
797:         .iter()
798:         .map(|s| (s.name.clone(), s.pid))
799:         .collect();
800: 
801:     if sessions.is_empty() {
802:         if flags.json {
803:             print_json_value(json!({
804:                 "success": true,
805:                 "data": { "closed": 0, "sessions": [] },
806:             }));
807:         } else {
808:             println!("No active sessions");
809:         }
810:         return;
811:     }
812: 
813:     let mut closed: Vec<String> = Vec::new();
814:     let mut failed: Vec<(String, String)> = Vec::new();
815: 
816:     for (session, pid) in &sessions {
817:         let cmd = json!({ "id": gen_id(), "action": "close" });
818:         match send_command(cmd, session) {
819:             Ok(resp) if resp.success => closed.push(session.clone()),
820:             Ok(resp) => {
821:                 let err = resp.error.unwrap_or_else(|| "Unknown error".to_string());
822:                 failed.push((session.clone(), err));
823:             }
824:             Err(_) => {
825:                 // Daemon is unreachable despite its process existing.
826:                 // Force-kill the process and clean up stale files so future
827:                 // sessions are not poisoned.
828:                 #[cfg(unix)]
829:                 unsafe {
830:                     libc::kill(*pid as i32, libc::SIGKILL);
831:                 }
832:                 #[cfg(windows)]
833:                 unsafe {
834:                     let handle = OpenProcess(1, 0, *pid); // PROCESS_TERMINATE = 1
835:                     if handle != 0 {
836:                         windows_sys::Win32::System::Threading::TerminateProcess(handle, 1);
837:                         CloseHandle(handle);
838:                     }
839:                 }
840:                 cleanup_stale_files(session);
841:                 closed.push(session.clone());
842:             }
843:         }
844:     }
845: 
846:     if flags.json {
847:         print_json_value(json!({
848:             "success": failed.is_empty(),
849:             "data": {
850:                 "closed": closed.len(),
851:                 "sessions": closed,
852:                 "failed": failed.iter().map(|(s, e)| json!({"session": s, "error": e})).collect::<Vec<_>>(),
853:             },
854:         }));
855:     } else {
856:         for s in &closed {
857:             println!("{} Closed session: {}", color::green("✓"), s);
858:         }
859:         for (s, e) in &failed {
860:             eprintln!("{} Failed to close {}: {}", color::error_indicator(), s, e);
861:         }
862:         if closed.is_empty() && !failed.is_empty() {
863:             exit(1);
864:         }
865:     }
866: 
867:     if !failed.is_empty() {
868:         exit(1);
869:     }
870: }
