872: fn main() {
873:     // Rust ignores SIGPIPE by default, causing println! to panic on broken pipes.
874:     // Reset to SIG_DFL so the OS terminates the process cleanly instead.
875:     #[cfg(unix)]
876:     unsafe {
877:         libc::signal(libc::SIGPIPE, libc::SIG_DFL);
878:     }
879: 
880:     // Prevent MSYS/Git Bash path translation from mangling arguments
881:     #[cfg(windows)]
882:     {
883:         env::set_var("MSYS_NO_PATHCONV", "1");
884:         env::set_var("MSYS2_ARG_CONV_EXCL", "*");
885:     }
886: 
887:     // Native daemon mode: when AGENT_BROWSER_DAEMON is set, run as the daemon process
888:     if env::var("AGENT_BROWSER_DAEMON").is_ok() {
889:         // Ignore SIGPIPE so the daemon isn't killed when the parent drops
890:         // the piped stderr handle after confirming the daemon is ready.
891:         #[cfg(unix)]
892:         unsafe {
893:             libc::signal(libc::SIGPIPE, libc::SIG_IGN);
894:         }
895:         let session = env::var("AGENT_BROWSER_SESSION").unwrap_or_else(|_| "default".to_string());
896:         let rt = tokio::runtime::Runtime::new().expect("Failed to create tokio runtime");
897:         rt.block_on(native::daemon::run_daemon(&session));
898:         return;
899:     }
900: 
901:     // Standalone dashboard server mode
902:     if env::var("AGENT_BROWSER_DASHBOARD").is_ok() {
903:         let port: u16 = env::var("AGENT_BROWSER_DASHBOARD_PORT")
904:             .ok()
905:             .and_then(|s| s.parse().ok())
906:             .unwrap_or(4848);
907:         let rt = tokio::runtime::Runtime::new().expect("Failed to create tokio runtime");
908:         rt.block_on(native::stream::run_dashboard_server(port));
909:         return;
910:     }
911: 
912:     let args: Vec<String> = env::args().skip(1).collect();
913:     let mut flags = parse_flags(&args);
914:     if flags.restore_uses_session {
915:         flags.restore = Some(flags.session.clone());
916:     }
917:     if let Some(ref namespace) = flags.namespace {
918:         env::set_var("AGENT_BROWSER_NAMESPACE", namespace);
919:     }
920:     let clean = clean_args(&args);
921: 
922:     let has_help = args.iter().any(|a| a == "--help" || a == "-h");
923:     let has_version = args.iter().any(|a| a == "--version" || a == "-V");
924: 
925:     if has_help {
926:         if let Some(cmd) = clean.first() {
927:             if print_command_help(cmd) {
928:                 return;
929:             }
930:         }
931:         print_help();
932:         return;
933:     }
934: 
935:     if has_version {
936:         print_version();
937:         return;
938:     }
939: 
940:     if clean.is_empty() {
941:         print_help();
942:         return;
943:     }
944: 
945:     // Handle install separately
946:     if clean.first().map(|s| s.as_str()) == Some("install") {
947:         let with_deps = args.iter().any(|a| a == "--with-deps" || a == "-d");
948:         run_install(with_deps);
949:         return;
950:     }
951: 
952:     // Handle upgrade separately
953:     if clean.first().map(|s| s.as_str()) == Some("upgrade") {
954:         run_upgrade();
955:         return;
956:     }
957: 
958:     // Handle doctor separately (doesn't need daemon; spawns its own scratch
959:     // session for the live launch test).
960:     if clean.first().map(|s| s.as_str()) == Some("doctor") {
961:         let opts = doctor::DoctorOptions {
962:             offline: args.iter().any(|a| a == "--offline"),
963:             quick: args.iter().any(|a| a == "--quick"),
964:             fix: args.iter().any(|a| a == "--fix"),
965:             json: flags.json,
966:         };
967:         exit(doctor::run_doctor(opts));
968:     }
969: 
970:     // Handle dashboard subcommand
971:     if clean.first().map(|s| s.as_str()) == Some("dashboard") {
972:         match clean.get(1).map(|s| s.as_str()) {
973:             Some("start") | None => {
974:                 let port = clean
975:                     .iter()
976:                     .position(|a| a == "--port")
977:                     .and_then(|i| clean.get(i + 1))
978:                     .and_then(|s| s.parse::<u16>().ok())
979:                     .unwrap_or(4848);
980:                 run_dashboard_start(port, flags.json);
981:                 return;
982:             }
983:             Some("stop") => {
984:                 run_dashboard_stop(flags.json);
985:                 return;
986:             }
987:             Some(unknown) => {
988:                 eprintln!(
989:                     "{} Unknown dashboard subcommand: {}",
990:                     color::error_indicator(),
991:                     unknown
992:                 );
993:                 exit(1);
994:             }
995:         }
996:     }
997: 
998:     // Handle profiles command (doesn't need daemon)
999:     if clean.first().map(|s| s.as_str()) == Some("profiles") {
1000:         run_profiles(flags.json);
1001:         return;
1002:     }
1003: 
1004:     // Handle skills command (doesn't need daemon)
1005:     if clean.first().map(|s| s.as_str()) == Some("skills") {
1006:         skills::run_skills(&clean, flags.json);
1007:         return;
1008:     }
1009: 
1010:     // Handle plugin registry commands (doesn't need daemon)
1011:     if matches!(
1012:         clean.first().map(|s| s.as_str()),
1013:         Some("plugin") | Some("plugins")
1014:     ) {
1015:         plugins::run_plugin_command(&clean, &flags.plugins, flags.json);
1016:         return;
1017:     }
1018: 
1019:     // Handle MCP stdio server mode. This must never share stdout with normal
1020:     // CLI output because stdout is reserved for JSON-RPC protocol messages.
1021:     if clean.first().map(|s| s.as_str()) == Some("mcp") {
1022:         if let Err(err) = mcp::run_mcp(&clean[1..]) {
1023:             eprintln!("{} {}", color::error_indicator(), err);
1024:             exit(1);
1025:         }
1026:         return;
1027:     }
1028: 
1029:     // Handle session separately (doesn't need daemon)
1030:     if clean.first().map(|s| s.as_str()) == Some("session") {
1031:         run_session(&clean, &flags.session, flags.json);
1032:         return;
1033:     }
1034: 
1035:     // Handle close --all: close all active sessions
1036:     if matches!(
1037:         clean.first().map(|s| s.as_str()),
1038:         Some("close") | Some("quit") | Some("exit")
1039:     ) && clean.iter().any(|a| a == "--all")
1040:     {
1041:         run_close_all(&flags);
1042:         return;
1043:     }
1044: 
1045:     // Handle chat command
1046:     if clean.first().map(|s| s.as_str()) == Some("chat") {
1047:         let message = if clean.len() > 1 {
1048:             Some(clean[1..].join(" "))
1049:         } else {
1050:             None
1051:         };
1052:         chat::run_chat(&flags, message);
1053:         return;
1054:     }
1055: 
1056:     let mut cmd = match parse_command(&clean, &flags) {
1057:         Ok(c) => c,
1058:         Err(e) => {
1059:             if flags.json {
1060:                 let error_type = match &e {
1061:                     ParseError::UnknownCommand { .. } => "unknown_command",
1062:                     ParseError::UnknownSubcommand { .. } => "unknown_subcommand",
1063:                     ParseError::MissingArguments { .. } => "missing_arguments",
1064:                     ParseError::InvalidValue { .. } => "invalid_value",
1065:                     ParseError::InvalidSessionName { .. } => "invalid_session_name",
1066:                 };
1067:                 print_json_error_with_type(e.format(), error_type);
1068:             } else {
1069:                 eprintln!("{}", color::red(&e.format()));
1070:             }
1071:             exit(1);
1072:         }
1073:     };
1074: 
1075:     // Handle --password-stdin for auth save
1076:     if cmd.get("action").and_then(|v| v.as_str()) == Some("auth_save") {
1077:         if cmd.get("password").is_some() {
1078:             eprintln!(
1079:                 "{} Passwords on the command line may be visible in process listings and shell history. Use --password-stdin instead.",
1080:                 color::warning_indicator()
1081:             );
1082:         }
1083:         if cmd
1084:             .get("passwordStdin")
1085:             .and_then(|v| v.as_bool())
1086:             .unwrap_or(false)
1087:         {
1088:             let mut pass = String::new();
1089:             if std::io::stdin().read_line(&mut pass).is_err() || pass.is_empty() {
1090:                 eprintln!(
1091:                     "{} Failed to read password from stdin",
1092:                     color::error_indicator()
1093:                 );
